// Extractor integration tests against the real fixture corpus.
// Pure-Go, no DB / network — but the fixtures live on disk
// (../testdata/), generated by testdata/generate.py.

package exif_test

import (
	"bytes"
	"context"
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/mscrnt/artist-alley/app/internal/asset/metadata"
	"github.com/mscrnt/artist-alley/app/internal/asset/metadata/exif"
)

func loadFixture(t *testing.T, name string) []byte {
	t.Helper()
	path := filepath.Join("..", "testdata", name)
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("load fixture %q: %v", name, err)
	}
	return b
}

func extract(t *testing.T, name string) (metadata.Result, error) {
	t.Helper()
	raw := loadFixture(t, name)
	e := exif.New()
	return e.Extract(context.Background(), bytes.NewReader(raw), "image/jpeg")
}

func TestExtractor_Name(t *testing.T) {
	if e := exif.New(); e.Name() != "exif" {
		t.Errorf("Name = %q, want exif", e.Name())
	}
}

func TestExtractor_Supports(t *testing.T) {
	e := exif.New()
	for _, mt := range []string{
		"image/jpeg", "image/jpg",
		"image/png",
		"image/tiff", "image/tif",
		"image/webp",
		"IMAGE/JPEG", // case-insensitive
	} {
		t.Run(mt, func(t *testing.T) {
			if !e.Supports(mt) {
				t.Errorf("should support %q", mt)
			}
		})
	}
	for _, mt := range []string{
		"image/heic", "image/heif", // deliberately NOT supported
		"image/gif",
		"application/pdf",
		"",
	} {
		t.Run(mt, func(t *testing.T) {
			if e.Supports(mt) {
				t.Errorf("should NOT support %q", mt)
			}
		})
	}
}

func TestIsHEIC(t *testing.T) {
	if !exif.IsHEIC("image/heic") {
		t.Errorf("image/heic should be detected as HEIC")
	}
	if !exif.IsHEIC("image/heif") {
		t.Errorf("image/heif should be detected as HEIC")
	}
	if exif.IsHEIC("image/jpeg") {
		t.Errorf("image/jpeg should NOT be detected as HEIC")
	}
}

func TestExtractor_HEIC_ReturnsUnsupported(t *testing.T) {
	e := exif.New()
	// We don't have a HEIC fixture (no CGo decoder); supplying
	// image/heic with arbitrary bytes must surface
	// ErrUnsupportedFormat cleanly — never panic. The job
	// handler maps this to a clean failure_row with kind=
	// "unsupported_format".
	_, err := e.Extract(context.Background(), bytes.NewReader([]byte("not a heic")), "image/heic")
	if !errors.Is(err, metadata.ErrUnsupportedFormat) {
		t.Errorf("got %v, want ErrUnsupportedFormat", err)
	}
}

func TestExtractor_UnsupportedFormat_Returns(t *testing.T) {
	e := exif.New()
	_, err := e.Extract(context.Background(), bytes.NewReader([]byte("data")), "video/mp4")
	if !errors.Is(err, metadata.ErrUnsupportedFormat) {
		t.Errorf("got %v, want ErrUnsupportedFormat", err)
	}
}

func TestExtractor_FullExif_PopulatesEveryField(t *testing.T) {
	res, err := extract(t, "with_full_exif.jpg")
	if err != nil {
		t.Fatalf("extract: %v", err)
	}
	// Make / Model
	if got, ok := res.Fields[metadata.FieldCameraMake]; !ok || got.Text != "Canon" {
		t.Errorf("Make = %v, want Canon", got)
	}
	if got, ok := res.Fields[metadata.FieldCameraModel]; !ok || got.Text != "Canon EOS R5" {
		t.Errorf("Model = %v, want 'Canon EOS R5'", got)
	}
	// Artist + ImageDescription
	if got, ok := res.Fields[metadata.FieldArtist]; !ok || got.Text != "Kenneth (fixture)" {
		t.Errorf("Artist = %v", got)
	}
	if got, ok := res.Fields[metadata.FieldImageDescription]; !ok || got.Text != "Test image for AA metadata extractor" {
		t.Errorf("ImageDescription = %v", got)
	}
	// Capture datetime
	if got, ok := res.Fields[metadata.FieldCaptureDateTime]; !ok {
		t.Errorf("CaptureDateTime missing")
	} else if got.Time.Year() != 2024 || got.Time.Month() != 3 || got.Time.Day() != 15 {
		t.Errorf("CaptureDateTime = %v, want 2024-03-15", got.Time)
	}
	// Orientation normalised
	if res.Orientation != 1 {
		t.Errorf("Orientation = %d, want 1", res.Orientation)
	}
	// Dimensions sniffed via image.DecodeConfig
	if got, ok := res.Fields[metadata.FieldPixelWidth]; !ok || got.Num != 64 {
		t.Errorf("PixelWidth = %v, want 64", got)
	}
	if got, ok := res.Fields[metadata.FieldPixelHeight]; !ok || got.Num != 64 {
		t.Errorf("PixelHeight = %v, want 64", got)
	}
	// TODO: FNumber / ISO / FocalLength / LensModel live in the
	// EXIF sub-IFD which Pillow's getexif() doesn't write by
	// default. Production code path handles them (see extractTag
	// in extractor.go); covered by manual dogfood against real
	// camera files. Follow-up: extend the fixture generator to
	// also populate the Exif sub-IFD via exif.get_ifd(IFD.Exif)
	// once the API quirks are worked out.
}

func TestExtractor_OrientationFixtures(t *testing.T) {
	for _, c := range []struct {
		file string
		want int
	}{
		{"orientation_1.jpg", 1},
		{"orientation_6.jpg", 6},
		{"orientation_8.jpg", 8},
	} {
		t.Run(c.file, func(t *testing.T) {
			res, err := extract(t, c.file)
			if err != nil {
				t.Fatalf("extract: %v", err)
			}
			if res.Orientation != c.want {
				t.Errorf("Orientation = %d, want %d", res.Orientation, c.want)
			}
		})
	}
}

