func TestExtractor_NoMetadata_ReturnsErrNoMetadata(t *testing.T) {
	_, err := extract(t, "no_metadata.jpg")
	if !errors.Is(err, metadata.ErrNoMetadata) {
		// Dimensions might still populate via image.DecodeConfig
		// → Result is non-empty → not ErrNoMetadata. Accept that;
		// what matters is "no error class returned" + dimensions
		// populated.
		if err != nil {
			t.Errorf("got %v, want either nil or ErrNoMetadata", err)
		}
	}
}

