func TestExtractor_FutureDate_ExtractorReturnsValue_ValidatorRejects(t *testing.T) {
	res, err := extract(t, "future_date.jpg")
	if err != nil {
		t.Fatalf("extract: %v", err)
	}
	got, ok := res.Fields[metadata.FieldCaptureDateTime]
	if !ok {
		t.Fatalf("CaptureDateTime missing — extractor should pull the raw value")
	}
	if got.Time.Year() != 3000 {
		t.Errorf("year = %d, want 3000 (validator rejects this downstream)", got.Time.Year())
	}
	// Validator should reject this value at the apply layer.
	if _, vErr := metadata.ValidateValue(got, 0); vErr == nil {
		t.Errorf("validator should reject year-3000 datetime")
	}
}

